  ('Geography', 'Eduqas', 'gcse', '1.2', 'Urban and Rural Processes and Change in the UK', 'What is a sustainable community?', 'A place with good housing, jobs, transport, services and environment for current and future residents.', 30),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is development?', 'The process of improving people''s standard of living and quality of life.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is GNI per capita?', 'Gross national income divided by the population, a measure of average wealth.', 2),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is the Human Development Index?', 'A measure of development combining life expectancy, education and income.', 3),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is life expectancy?', 'The average number of years a person is expected to live.', 4),
