  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is infant mortality rate?', 'The number of babies who die before their first birthday per 1000 live births.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is a high-income country (HIC)?', 'A wealthy, developed country, e.g. the UK or USA.', 7),
