  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is aid?', 'Help given by one country or organisation to another, e.g. money, food or expertise.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is short-term aid?', 'Emergency help after a disaster, e.g. food, shelter and medicine.', 14),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is long-term aid?', 'Help to improve development over time, e.g. building schools and wells.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is fair trade?', 'A system ensuring producers in poorer countries receive a fair price and good working conditions.', 16),
