  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is a top-down development project?', 'A large-scale project planned by governments or organisations, e.g. a dam.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'A Global Perspective on Development Issues', 'What is a bottom-up development project?', 'A small-scale project run by local communities, e.g. a village well.', 30),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What are the four processes of coastal erosion?', 'Hydraulic action, abrasion, attrition and solution.', 1),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is hydraulic action?', 'Waves force air into cracks in the cliff, which breaks the rock apart.', 2),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is abrasion?', 'Rocks carried by waves are thrown against the cliff, wearing it away.', 3),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is attrition?', 'Rocks carried by waves knock against each other, becoming smaller and rounder.', 4),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is solution?', 'Seawater dissolves soluble rocks such as chalk and limestone.', 5),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is longshore drift?', 'The movement of sediment along the coast by waves approaching at an angle.', 6),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is the swash?', 'The movement of water up the beach after a wave breaks.', 7),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is the backwash?', 'The movement of water back down the beach under gravity.', 8),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a constructive wave?', 'A low, gentle wave with a strong swash and weak backwash, which builds up beaches.', 9),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a destructive wave?', 'A tall, steep wave with a weak swash and strong backwash, which erodes beaches.', 10),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is fetch?', 'The distance over which the wind blows across open water, affecting wave size.', 11),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'How is a headland formed?', 'Resistant rock erodes more slowly than softer rock, leaving land sticking out into the sea.', 12),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'How is a bay formed?', 'Softer rock is eroded more quickly, forming a curved inlet between headlands.', 13),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'How is a stack formed?', 'Waves erode a crack into a cave, then an arch; the arch roof collapses, leaving a stack.', 14),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a stump?', 'The remains of a stack after it has been eroded further.', 15),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a wave-cut platform?', 'A flat area of rock at the base of a cliff, left as the cliff retreats through erosion.', 16),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'How is a spit formed?', 'Longshore drift carries sediment past a bend in the coastline, where it is deposited in the sea.', 17),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a bar?', 'A spit that grows across a bay, joining two headlands and sometimes trapping a lagoon.', 18),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a beach?', 'A deposit of sand and shingle along the coast, formed by constructive waves.', 19),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a sand dune?', 'A hill of sand formed when wind blows sand inland, trapped by vegetation such as marram grass.', 20),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is hard engineering?', 'Building artificial structures to control the sea, e.g. sea walls, groynes and rock armour.', 21),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is soft engineering?', 'Working with natural processes to manage the coast, e.g. beach nourishment and dune regeneration.', 22),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a sea wall?', 'A concrete wall that reflects waves back out to sea; effective but expensive.', 23),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a groyne?', 'A wooden or rock barrier built out to sea to trap sediment moved by longshore drift.', 24),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is rock armour?', 'Large boulders placed at the foot of a cliff to absorb wave energy.', 25),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is beach nourishment?', 'Adding sand or shingle to a beach to make it wider, absorbing wave energy.', 26),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is managed retreat?', 'Allowing the coast to erode or flood naturally in low-value areas.', 27),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is sea-level rise''s effect on coasts?', 'It increases flooding and erosion, threatening homes, farmland and habitats.', 28),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is a Shoreline Management Plan?', 'A plan that decides how each stretch of coast should be managed: hold the line, advance, retreat or do nothing.', 29),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Coasts and Coastal Management', 'What is mass movement at the coast?', 'The downhill movement of material under gravity, e.g. slumping and rockfalls.', 30),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is the source of a river?', 'Where the river begins, often in upland areas.', 1),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is the mouth of a river?', 'Where the river meets the sea or a lake.', 2),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a tributary?', 'A smaller river that joins a larger one.', 3),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a confluence?', 'The point where two rivers meet.', 4),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a drainage basin?', 'The area of land drained by a river and its tributaries.', 5),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a watershed?', 'The boundary of a drainage basin, usually high ground.', 6),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'How does a river change from source to mouth?', 'It becomes wider and deeper, with a greater discharge and gentler gradient.', 7),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is vertical erosion?', 'Erosion that deepens the river channel, common in the upper course.', 8),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is lateral erosion?', 'Erosion that widens the river channel, common in the middle and lower course.', 9),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What are the four types of river transportation?', 'Traction, saltation, suspension and solution.', 10),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is traction?', 'Large boulders are rolled along the river bed.', 11),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is saltation?', 'Small pebbles bounce along the river bed.', 12),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is suspension?', 'Fine particles are carried in the water.', 13),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'When does a river deposit sediment?', 'When it loses energy, e.g. when it slows down on the inside of a bend or enters the sea.', 14),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'How is a waterfall formed?', 'Soft rock beneath hard rock is eroded, creating an overhang that collapses; the waterfall retreats, leaving a gorge.', 15),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a gorge?', 'A steep-sided valley formed as a waterfall retreats upstream.', 16),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a V-shaped valley?', 'A steep valley in the upper course, formed by vertical erosion and weathering.', 17),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is interlocking spurs?', 'Hills that stick out alternately on either side of a river in the upper course.', 18),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'How is a meander formed?', 'Erosion on the outside of a bend (fast flow) and deposition on the inside (slow flow).', 19),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'How is an oxbow lake formed?', 'Erosion narrows the neck of a meander until the river cuts through it during a flood; deposition seals off the old loop.', 20),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a floodplain?', 'Flat land either side of a river in the lower course, covered with deposits during floods.', 21),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a levée?', 'A raised bank along a river, formed by deposition of sediment during floods.', 22),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a hydrograph?', 'A graph showing river discharge over time, often in relation to rainfall.', 23),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is lag time?', 'The time between peak rainfall and peak discharge.', 24),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What factors increase flood risk?', 'Heavy rainfall, impermeable rock, steep slopes, urbanisation and deforestation.', 25),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'How does urbanisation increase flood risk?', 'Impermeable surfaces increase surface runoff, and drains carry water quickly to rivers.', 26),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a flood defence?', 'A structure or strategy to reduce flooding, e.g. dams, embankments, flood relief channels.', 27),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is a flood relief channel?', 'An artificial channel that diverts water away from a town when river levels are high.', 28),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is river restoration?', 'Returning a river to a more natural state to reduce flood risk and improve habitats.', 29),
  ('Geography', 'Eduqas', 'gcse', '2.2', 'Rivers and River Management', 'What is flood zoning?', 'Restricting building on floodplains in areas at high risk of flooding.', 30),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is weather?', 'The day-to-day conditions of the atmosphere, such as temperature, rainfall and wind.', 1),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is climate?', 'The average weather conditions of a place over a long period (usually 30 years).', 2),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a high-pressure system?', 'An area of sinking air, bringing settled, dry weather (an anticyclone).', 3),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a low-pressure system?', 'An area of rising air, bringing cloudy, wet and windy weather (a depression).', 4),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What weather does an anticyclone bring in summer?', 'Hot, dry, sunny weather.', 5),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What weather does an anticyclone bring in winter?', 'Cold, clear days, frosty nights and fog.', 6),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a depression?', 'A low-pressure weather system that brings wind and rain.', 7),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a warm front?', 'The boundary where warm air rises over cold air, bringing steady rain.', 8),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a cold front?', 'The boundary where cold air pushes under warm air, bringing heavy rain and gusty winds.', 9),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is an air mass?', 'A large body of air with similar temperature and moisture.', 10),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a maritime air mass?', 'An air mass that has travelled over the sea, bringing moist air.', 11),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a continental air mass?', 'An air mass that has travelled over land, bringing dry air.', 12),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is the UK''s climate like?', 'Temperate maritime: mild winters, cool summers, and rain throughout the year.', 13),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'Why is western Britain wetter than eastern Britain?', 'Prevailing south-westerly winds bring moist air from the Atlantic, which rises over western hills (relief rainfall).', 14),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is relief rainfall?', 'Rain caused when air is forced to rise over high ground, cools and condenses.', 15),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is convectional rainfall?', 'Rain caused when the ground heats up, warm air rises, cools and condenses.', 16),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is frontal rainfall?', 'Rain caused when warm air meets cold air and is forced to rise.', 17),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is the North Atlantic Drift?', 'A warm ocean current that keeps the UK milder than other places at the same latitude.', 18),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is global atmospheric circulation?', 'The worldwide movement of air in cells (Hadley, Ferrel and Polar), which creates climate zones.', 19),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is the Hadley cell?', 'The circulation cell between the equator and about 30°, creating rainforests and deserts.', 20),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'Why is there low pressure at the equator?', 'Intense heating makes air rise.', 21),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'Why are deserts found at about 30° north and south?', 'Air sinks there, creating high pressure and dry conditions.', 22),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a tropical storm?', 'An intense low-pressure system with very strong winds and heavy rain, forming over warm oceans.', 23),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What conditions are needed for a tropical storm to form?', 'Ocean temperatures above 27 °C, low wind shear, and being at least 5° from the equator.', 24),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is extreme weather?', 'Weather that is much more severe than usual, e.g. heatwaves, floods and storms.', 25),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'Give an example of extreme weather in the UK.', 'Storm Desmond (2015), the 2022 heatwave, or the Somerset Levels floods (2014).', 26),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is a heatwave?', 'A period of unusually hot weather.', 27),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is drought?', 'A long period with much less rainfall than normal.', 28),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is microclimate?', 'The climate of a small area that differs from the surrounding area, e.g. an urban heat island.', 29),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Weather and Climate', 'What is an urban heat island?', 'A city that is warmer than the surrounding countryside due to buildings, roads and human activity.', 30),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is climate change?', 'A long-term change in the Earth''s climate, including temperature and rainfall patterns.', 1),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is the greenhouse effect?', 'Gases in the atmosphere trap heat from the Sun, keeping the Earth warm.', 2),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is the enhanced greenhouse effect?', 'Human activities increase greenhouse gases, trapping more heat and causing global warming.', 3),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'Name three greenhouse gases.', 'Carbon dioxide, methane and nitrous oxide.', 4),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What are the human causes of climate change?', 'Burning fossil fuels, deforestation, farming (methane from cattle), and industry.', 5),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What are the natural causes of climate change?', 'Changes in the Earth''s orbit, volcanic eruptions and variations in solar output.', 6),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is the evidence for climate change?', 'Rising global temperatures, melting ice caps, rising sea levels, and ice core records.', 7),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What do ice cores show?', 'Air bubbles trapped in ice show past levels of CO₂ and temperature.', 8),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What are the effects of climate change on the environment?', 'Rising sea levels, melting ice, more extreme weather, and loss of habitats.', 9),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What are the effects of climate change on people?', 'Flooding, food shortages, water shortages, and health problems.', 10),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is mitigation?', 'Reducing the causes of climate change, e.g. cutting emissions.', 11),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is adaptation?', 'Changing how we live to cope with the effects of climate change.', 12),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'Give examples of mitigation.', 'Renewable energy, planting trees, carbon capture, and international agreements.', 13),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'Give examples of adaptation.', 'Flood defences, drought-resistant crops, and changing farming practices.', 14),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is carbon capture and storage?', 'Capturing CO₂ from power stations and storing it underground.', 15),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is the Paris Agreement?', 'A 2015 international agreement to limit global warming to well below 2 °C.', 16),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is a carbon footprint?', 'The total amount of greenhouse gases produced by a person, organisation or activity.', 17),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'How can individuals reduce their carbon footprint?', 'Using public transport, saving energy, recycling, and eating less meat.', 18),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'How does climate change affect the UK?', 'Hotter summers, wetter winters, more flooding and rising sea levels.', 19),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'How does climate change affect poorer countries?', 'They are often more vulnerable to droughts, floods and storms, with fewer resources to adapt.', 20),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is sea-level rise caused by?', 'Melting ice sheets and glaciers, and thermal expansion of water.', 21),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is thermal expansion?', 'Water expanding as it warms, raising sea levels.', 22),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is the Quaternary period?', 'The last 2.6 million years, with glacial and interglacial periods.', 23),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is an interglacial period?', 'A warmer period between glacial periods.', 24),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'How does deforestation contribute to climate change?', 'Trees absorb CO₂; removing them increases CO₂ in the atmosphere.', 25),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is the role of methane in climate change?', 'Methane is a powerful greenhouse gas released by cattle, rice farming and landfill.', 26),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is renewable energy?', 'Energy from sources that won''t run out, e.g. wind, solar and hydroelectric power.', 27),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is a climate refugee?', 'Someone forced to move because of the effects of climate change.', 28),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'How do rising temperatures affect ecosystems?', 'Species may move, adapt or become extinct, e.g. coral bleaching.', 29),
  ('Geography', 'Eduqas', 'gcse', '2.4', 'Climate Change — Cause and Effect', 'What is coral bleaching?', 'Corals expel algae when water is too warm, turning white and possibly dying.', 30),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is a biome?', 'A large-scale ecosystem with a distinctive climate, vegetation and animal life.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Where is the savanna found?', 'Between about 5° and 20° north and south of the Equator, e.g. East Africa, northern Australia and Brazil.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is the savanna''s climate like?', 'Hot all year, with a wet season and a long dry season.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Why does the savanna have wet and dry seasons?', 'The ITCZ moves north and south with the overhead sun, bringing rain for part of the year.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What vegetation dominates the savanna?', 'Grasses with scattered drought-resistant trees such as acacia and baobab.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'How are acacia trees adapted to the savanna?', 'Deep roots reach groundwater, small leaves reduce water loss and thorns deter grazers.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'How is the baobab tree adapted?', 'It stores water in its huge trunk and sheds leaves in the dry season.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What role does fire play in the savanna?', 'Dry-season fires stop trees taking over and recycle nutrients; grasses regrow quickly from roots.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is the Serengeti–Mara ecosystem known for?', 'The great wildebeest migration of over a million animals following the rains.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Why is decomposition slow in the savanna?', 'Dead grass lies dry for months during the dry season.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is a food web?', 'A diagram showing the feeding relationships between organisms in an ecosystem.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is a producer?', 'An organism, usually a plant, that makes its own food by photosynthesis.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Why is energy lost along a food chain?', 'Energy is used for movement, heat and life processes at each trophic level.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is Kenfig National Nature Reserve?', 'A sand dune system with dune slacks and a pool in South Wales — a small-scale UK ecosystem.', 14),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is a dune slack?', 'A damp hollow between dunes where the water table is near the surface; very species-rich.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Which rare plant is protected at Kenfig?', 'The fen orchid, which has risen from about 200 to over 4,000 plants.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Why is Kenfig becoming too stable?', 'Loss of grazing and nitrogen deposition let coarse plants and scrub spread over bare sand.', 17),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'How is Kenfig managed?', 'Scrub clearance, turf stripping, reintroduced grazing and boardwalks to control visitors.', 18),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is an ecosystem?', 'A community of living things interacting with each other and their non-living environment.', 19),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is the climate of a tropical rainforest?', 'Hot (about 27 °C) and wet all year, with over 2000 mm of rain.', 20),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What are the layers of the rainforest?', 'Emergent layer, canopy, understorey and forest floor.', 21),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is the canopy?', 'The dense layer of tree tops that absorbs most sunlight.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What are buttress roots?', 'Large roots that support tall trees in shallow soils.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What are drip tips?', 'Pointed leaves that allow heavy rain to run off quickly.', 24),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What are lianas?', 'Woody vines that climb trees to reach sunlight.', 25),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What are epiphytes?', 'Plants that grow on other plants to reach light, e.g. orchids.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'How are animals adapted to the rainforest?', 'E.g. sloths move slowly and are camouflaged; monkeys have prehensile tails; frogs have sticky feet.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is the nutrient cycle in rainforests?', 'Nutrients are rapidly recycled from leaf litter to plants, so the soil is poor.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'Why is rainforest soil infertile?', 'Heavy rain washes nutrients away (leaching), and nutrients are held in plants.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'How Ecosystems Function', 'What is biodiversity?', 'The variety of living things in an area.', 30),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How do people modify ecosystems?', 'By clearing land for farming, logging, mining, building and tourism.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is the biggest driver of Amazon deforestation?', 'Cattle ranching.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Why is Borneo''s forest being cleared?', 'Mainly for palm oil plantations, plus logging and mining.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How is the savanna threatened?', 'Overgrazing, population growth, conversion to farmland, poaching and climate change.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What happens when savanna is overgrazed?', 'Vegetation is removed, soil is exposed and eroded, and land can turn to desert.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How does tourism affect the Maasai Mara?', 'It brings income but vehicles damage grassland and disturb animals.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Give a local effect of deforestation.', 'Soil erosion, loss of habitats and loss of livelihoods for indigenous people.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Give a global effect of deforestation.', 'More CO₂ released and less carbon stored, adding to climate change.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Why are ecosystems conserved?', 'For biodiversity, ecosystem services, climate regulation, livelihoods and future resources.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is sustainable management?', 'Using ecosystems to meet present needs without damaging them for future generations.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is selective logging?', 'Felling only certain mature trees, leaving the rest of the forest intact.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is ecotourism?', 'Small-scale tourism that protects the environment and benefits local people, e.g. Costa Rica.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is the Great Green Wall?', 'An African-led project to restore land across the Sahel with trees and sustainable farming.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is a debt-for-nature swap?', 'Cancelling part of a country''s debt in return for protecting forests.', 14),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is CITES?', 'An international agreement controlling trade in endangered species and some timber.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is REDD+?', 'A UN scheme paying countries to keep forests standing to reduce carbon emissions.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How does palm oil production harm Borneo?', 'It destroys orangutan habitat, drains peat and pollutes rivers.', 17),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is the RSPO?', 'The Roundtable on Sustainable Palm Oil, which certifies sustainably produced palm oil.', 18),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Why do indigenous land rights help protect forests?', 'Indigenous territories have much lower deforestation rates.', 19),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How can grazing be managed sustainably in the savanna?', 'By limiting herd sizes and rotating grazing to let grass recover.', 20),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How does poaching threaten the savanna?', 'It reduces populations of elephants and rhinos, upsetting food webs.', 21),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is a national park?', 'A protected area where development is restricted to conserve landscapes and wildlife.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Where are tropical rainforests found?', 'Near the equator, e.g. the Amazon, Congo Basin and Southeast Asia.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is deforestation?', 'The cutting down or removal of forests.', 24),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What are the causes of deforestation?', 'Logging, cattle ranching, farming (e.g. palm oil and soya), mining, road building and hydroelectric dams.', 25),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What are the impacts of deforestation?', 'Loss of biodiversity, soil erosion, climate change, and loss of indigenous people''s homes.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'How does deforestation contribute to climate change?', 'Trees store carbon; burning or cutting them releases CO₂, and fewer trees absorb CO₂.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What is sustainable forestry?', 'Managing forests so trees are replanted and the forest can continue to provide resources.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'What role do indigenous people play in rainforests?', 'They often live sustainably and help protect forests from exploitation.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Ecosystems Under Threat', 'Why is the Amazon rainforest important globally?', 'It stores carbon, regulates climate, has huge biodiversity, and provides medicines.', 30),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is water security?', 'Having reliable access to enough safe, clean water.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is water scarcity?', 'When there isn''t enough water to meet demand.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is physical water scarcity?', 'Not enough water available because of the climate or overuse.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is economic water scarcity?', 'Water is available but people can''t afford the infrastructure to access it.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'Why is demand for water increasing?', 'Population growth, economic development, and increased use in farming and industry.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'Where is water surplus in the UK?', 'The north and west, which have high rainfall and low population.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'Where is water deficit in the UK?', 'The south-east, which has lower rainfall and high population.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is a water transfer scheme?', 'Moving water from areas of surplus to areas of deficit.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is a reservoir?', 'An artificial lake used to store water.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What are the advantages of dams and reservoirs?', 'Water supply, hydroelectric power, flood control and recreation.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What are the disadvantages of dams and reservoirs?', 'Flooding of land and homes, loss of habitats, and high costs.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is desalination?', 'Removing salt from seawater to make fresh water.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is a disadvantage of desalination?', 'It is expensive and uses a lot of energy.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is groundwater?', 'Water stored underground in rocks (aquifers).', 14),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is water conservation?', 'Reducing water use, e.g. using water meters, efficient appliances and fixing leaks.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is greywater recycling?', 'Reusing water from sinks, showers and washing machines for flushing toilets or watering gardens.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is rainwater harvesting?', 'Collecting and storing rainwater for use.', 17),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'How does farming affect water supply?', 'Irrigation uses large amounts of water, and fertilisers can pollute rivers.', 18),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is water pollution?', 'Contamination of water by chemicals, sewage or waste.', 19),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is a water-borne disease?', 'A disease spread through contaminated water, e.g. cholera and typhoid.', 20),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'How can water supply be improved in poorer countries?', 'Wells, hand pumps, rainwater harvesting and water purification.', 21),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is a sustainable water supply?', 'Using water in a way that meets current needs without harming future supply.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is the water cycle?', 'The continuous movement of water between the sea, air and land.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is evaporation?', 'Water changing from liquid to gas.', 24),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is condensation?', 'Water vapour cooling and changing into liquid, forming clouds.', 25),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is precipitation?', 'Water falling from clouds as rain, snow, sleet or hail.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is infiltration?', 'Water soaking into the soil.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is surface runoff?', 'Water flowing over the ground into rivers.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is water stress?', 'When demand for water exceeds the available supply.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Resources and Management', 'What is a water conflict?', 'A dispute between groups or countries over access to water, e.g. over the Nile.', 30),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is desertification?', 'The process by which land in dry areas becomes degraded and turns into desert.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Which environments are most vulnerable to desertification?', 'Semi-arid areas on the edges of hot deserts, such as the Sahel.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Where is the Sahel?', 'A semi-arid belt south of the Sahara, stretching from Senegal to Sudan.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Why are desert fringes dry?', 'They lie near the sub-tropical high pressure belt, where sinking air prevents rain.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How has Sahel rainfall changed?', 'It fell sharply from the 1950s–60s to the 1970s–80s, causing severe droughts.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How does vegetation loss make desertification worse?', 'Less evapotranspiration means less local rainfall and exposed soil is eroded.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Name four human causes of desertification.', 'Overgrazing, over-cultivation, deforestation for fuelwood and over-abstraction of water.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is overgrazing?', 'Keeping too many animals on land, so vegetation is eaten faster than it regrows.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is over-cultivation?', 'Farming land too intensively without fallow periods, exhausting the soil.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Why do people cut trees in the Sahel?', 'For fuelwood, building and to clear land for farming.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How does population growth affect desertification?', 'More people need more food, fuel and water, increasing pressure on the land.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Give an impact of desertification on people.', 'Falling crop yields, food insecurity and migration to cities.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What are zai pits?', 'Small planting pits filled with manure that collect water and nutrients for crops.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What are stone lines (bunds)?', 'Lines of stones along contours that slow run-off and trap soil and water.', 14),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How can NGOs help reduce desertification?', 'By working with communities on tree planting, water harvesting and better farming.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Who are stakeholders in desertification?', 'Farmers, herders, governments, NGOs and international organisations, each with different views.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Name an international strategy against desertification.', 'The Great Green Wall or the UN Convention to Combat Desertification.', 17),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How might climate change affect desertification?', 'Higher temperatures and less reliable rainfall could increase it.', 18),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How does deforestation in the Sahel affect rainfall?', 'Less vegetation means less moisture recycled to the air, reducing local rain.', 19),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Why is soil erosion a problem in desertification?', 'Fertile topsoil is blown or washed away, so crops cannot grow.', 20),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Why do farmers in the Sahel overcultivate?', 'Rising population and poverty mean they need more food from the same land.', 21),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How does drought make desertification worse?', 'Plants die, leaving soil bare and easily eroded.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is desert soil like?', 'Sandy or stony, dry, and low in nutrients.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What are the causes of desertification?', 'Overgrazing, overcultivation, deforestation, population growth and climate change.', 24),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'Where is desertification a problem?', 'In semi-arid areas such as the Sahel in Africa.', 25),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'How can desertification be reduced?', 'Planting trees, water conservation, appropriate technology, and improving farming methods.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What are magic stones (bunds)?', 'Lines of stones that slow water runoff and trap soil, reducing erosion.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is the Great Green Wall?', 'A project to plant a belt of trees across the Sahel to stop desertification.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is overcultivation?', 'When land is farmed too intensively, exhausting the soil.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.4', 'Desertification', 'What is the Sahel?', 'A semi-arid region south of the Sahara, at risk of desertification.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'Eduqas' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
